from common import *
from transition import LatentTransition
import fcntl,time,os,platform
def main():
 protocol=read(E/'configs/protocol.json');assert read(E/'results/extraction.json')['passed'];assert not(E/'configs/model_selection_frozen.json').exists()
 for p,h in protocol['frozen_sha256'].items():assert sha(p)==h,p
 lock=(P/'runs/gpu.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);torch.set_num_threads(4);torch.set_float32_matmul_precision('high');torch.backends.cudnn.benchmark=False;m=reader();frozen_digest=digest_model(m);pairs=read(E/'data/public/pairs.json');train_idx=np.array([i for i,r in enumerate(pairs)if r['split']=='train']);tune_idx=np.array([i for i,r in enumerate(pairs)if r['dev_role']=='tune']);assert len(train_idx)==96 and len(tune_idx)==12
 data={}
 with np.load(E/'data/public/transition_inputs.npz')as z,np.load(E/'data/_private/training_targets_and_audit.npz')as t:
  assert set(z.files)=={'current_objects','current_scene','declared_actions'}
  for name,idx in [('train',train_idx),('tune',tune_idx)]:data[name]={k:torch.as_tensor(z[k][idx],device='cuda')for k in z.files};data[name].update({k:torch.as_tensor(t[k][idx],device='cuda')for k in ['next_objects','next_scene','after_y','after_valid']})
 tune_roots=torch.tensor([protocol['data']['dev_roles']['tune'].index(pairs[i]['root_id'])for i in tune_idx],device='cuda');weights=torch.tensor(protocol['loss']['class_weights_negative_positive'],device='cuda');allruns=[];started=time.perf_counter()
 save(E/'configs/runtime.json',{'torch':torch.__version__,'python':platform.python_version(),'device':torch.cuda.get_device_name(),'total_vram_bytes':torch.cuda.get_device_properties(0).total_memory,'cuda_version':torch.version.cuda,'pid':os.getpid(),'max_updates_each':600,'sequential_single_gpu':True})
 for seed in protocol['seeds']:
  for mode in protocol['modes']:
   rid=f'{mode}_seed{seed}';out=E/'runs'/rid;out.mkdir(exist_ok=False);(E/'models'/rid).mkdir(exist_ok=False);torch.manual_seed(seed);torch.cuda.manual_seed_all(seed);np.random.seed(seed);net=LatentTransition(mode).cuda();assert sum(p.numel()for p in net.parameters())==protocol['architectures'][mode]['parameters'];opt=torch.optim.AdamW(net.parameters(),lr=.001,weight_decay=.0001);gen=torch.Generator(device='cpu').manual_seed(10000+seed);init_digest=digest_model(net);torch.cuda.synchronize();torch.cuda.reset_peak_memory_stats();t0=time.perf_counter();event0=torch.cuda.Event(enable_timing=True);event1=torch.cuda.Event(enable_timing=True);event0.record();curve=[];checkpoints=[];log=(out/'curve.jsonl').open('w');perm=None
   for update in range(1,601):
    if(update-1)%6==0:perm=torch.randperm(96,generator=gen)
    ix=perm[((update-1)%6)*16:((update-1)%6+1)*16].to('cuda');batch={k:v[ix]for k,v in data['train'].items()};net.train();opt.zero_grad(set_to_none=True);hp,sp=net(batch['current_objects'],batch['current_scene'],batch['declared_actions']);lp=logits(m,hp,sp);bce=balanced_bce(lp,batch['after_y'],batch['after_valid'],weights);latent=.5*(F.smooth_l1_loss(hp,batch['next_objects'])+F.smooth_l1_loss(sp,batch['next_scene']));loss=bce+.05*latent;assert torch.isfinite(loss);loss.backward();grad=float(torch.nn.utils.clip_grad_norm_(net.parameters(),1.));opt.step();record={'update':update,'batch_BCE':float(bce.detach()),'batch_latent_SmoothL1':float(latent.detach()),'batch_total_loss':float(loss.detach()),'gradient_norm_before_clip':grad,'elapsed_wall_seconds':time.perf_counter()-t0};curve.append(record);log.write(json.dumps(record)+'\n')
    if update in protocol['selection']['checkpoints']:
     net.eval()
     with torch.inference_mode():
      d=data['tune'];hh,ss=net(d['current_objects'],d['current_scene'],d['declared_actions']);ll=logits(m,hh,ss);score=float(root_selection_score(ll,d['after_y'],d['after_valid'],weights,tune_roots))
     path=E/'models'/rid/f'update{update:04d}.pt';torch.save({'model':net.state_dict(),'optimizer':opt.state_dict(),'seed':seed,'mode':mode,'update':update,'protocol_sha256':sha(E/'configs/protocol.json'),'batch_generator_state':gen.get_state()},path);cp={'update':update,'tune_root_macro_BCE':score,'path':str(path),'sha256':sha(path)};checkpoints.append(cp);print(json.dumps({'run':rid,**cp,'train_batch_loss':record['batch_total_loss']},ensure_ascii=False),flush=True);save(out/'checkpoints.json',checkpoints)
   log.close();event1.record();torch.cuda.synchronize();wall=time.perf_counter()-t0;best=min(checkpoints,key=lambda x:(x['tune_root_macro_BCE'],x['update']));assert digest_model(m)==frozen_digest and all(p.grad is None for p in m.parameters());result={'run':rid,'seed':seed,'mode':mode,'updates':600,'parameters':sum(p.numel()for p in net.parameters()),'initial_state_digest':init_digest,'selected':best,'all_checkpoints':checkpoints,'wall_seconds':wall,'CUDA_elapsed_seconds':event0.elapsed_time(event1)/1000,'peak_torch_allocated_bytes':torch.cuda.max_memory_allocated(),'peak_torch_reserved_bytes':torch.cuda.max_memory_reserved(),'frozen_reader_digest_unchanged':True,'calibration_not_scored':True,'final_batch_loss':curve[-1]};save(out/'summary.json',result);allruns.append(result);save(E/'results/training_progress.json',{'completed_runs':len(allruns),'optimizer_updates':sum(x['updates']for x in allruns),'last_run':rid});del net,opt;torch.cuda.empty_cache()
 representatives={mode:min([r for r in allruns if r['mode']==mode],key=lambda x:(x['selected']['tune_root_macro_BCE'],x['seed']))['run']for mode in protocol['modes']};selection={'created_utc':now(),'protocol_sha256':sha(E/'configs/protocol.json'),'all_runs':allruns,'representative_run_per_mode':representatives,'C_calibration_not_scored':True,'selected_before_final_C_evaluation':True,'total_optimizer_updates':sum(r['updates']for r in allruns),'total_wall_seconds':time.perf_counter()-started,'frozen_candidate_digest':frozen_digest};assert selection['total_optimizer_updates']==5400;save(E/'configs/model_selection_frozen.json',selection);(E/'configs/model_selection_frozen.json').chmod(0o444);print('FIXED_TRAINING_COMPLETE',representatives,selection['total_wall_seconds'],flush=True)
if __name__=='__main__':main()
